import{_ as r,o as i,c as u,ah as s}from"./chunks/framework.D4KxWb5R.js";const m=JSON.parse('{"title":"Équipes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/administration/teams.md","filePath":"src/guide/administration/teams.md"}'),n={name:"guide/administration/teams.md"};function t(a,e,o,p,l,d){return i(),u("div",null,[...e[0]||(e[0]=[s('<h1 id="equipes" tabindex="-1">Équipes <a class="header-anchor" href="#equipes" aria-label="Permalink to &quot;Équipes&quot;">​</a></h1><p>Une équipe est un groupe de comptes nommés, responsable d&#39;un ou plusieurs produits. <strong>Administration → Équipes</strong> est réservé au PDG.</p><h2 id="ce-que-donne-une-equipe" tabindex="-1">Ce que donne une équipe <a class="header-anchor" href="#ce-que-donne-une-equipe" aria-label="Permalink to &quot;Ce que donne une équipe&quot;">​</a></h2><p>Chaque membre d&#39;une équipe responsable d&#39;un produit, quel que soit son poste :</p><ul><li>voit ce produit dans son périmètre et dans l&#39;intranet ;</li><li>ouvre son back-office par SSO, sans accès accordé compte par compte ;</li><li>reçoit l&#39;alerte quand le produit est désynchronisé, ou quand ses indicateurs ne peuvent plus être collectés.</li></ul><p>Un compte peut appartenir à plusieurs équipes.</p><h2 id="creer-ou-modifier-une-equipe" tabindex="-1">Créer ou modifier une équipe <a class="header-anchor" href="#creer-ou-modifier-une-equipe" aria-label="Permalink to &quot;Créer ou modifier une équipe&quot;">​</a></h2><ol><li><strong>Nouvelle équipe</strong> (ou ouvrez une équipe existante).</li><li><strong>Nom</strong> en anglais (obligatoire) et en français, <strong>département</strong> facultatif.</li><li><strong>Membres</strong> : recherchez et ajoutez les comptes.</li><li>Enregistrez.</li></ol><p>Les membres ajoutés ou retirés sont prévenus. Une équipe n&#39;est pas supprimée.</p><h2 id="rendre-une-equipe-responsable-d-un-produit" tabindex="-1">Rendre une équipe responsable d&#39;un produit <a class="header-anchor" href="#rendre-une-equipe-responsable-d-un-produit" aria-label="Permalink to &quot;Rendre une équipe responsable d&#39;un produit&quot;">​</a></h2><p>Les équipes se choisissent sur la fiche du produit, dans le <a href="./registry.html">registre</a>, section <strong>Équipes responsables</strong>.</p><h2 id="retirer-un-membre-ou-une-equipe" tabindex="-1">Retirer un membre ou une équipe <a class="header-anchor" href="#retirer-un-membre-ou-une-equipe" aria-label="Permalink to &quot;Retirer un membre ou une équipe&quot;">​</a></h2><p>Retirer un membre d&#39;une équipe, ou une équipe d&#39;une fiche produit, révoque les sessions et les jetons du compte pour les back-offices qu&#39;il perd, sauf s&#39;il y a accès par ailleurs (accès accordé ou autre équipe).</p><p>Toutes ces modifications sont inscrites au <a href="./logs.html">journal d&#39;administration</a>.</p>',14)])])}const q=r(n,[["render",t]]);export{m as __pageData,q as default};
